    "portal_welcome": "સ્વાસ્થ્ય સેતુમાં આપનું સ્વાગત છે",
    "portal_subline": "ચકાસાયેલ ઓળખપત્રો સાથે લૉગિન કરવા તમારી આરોગ્ય ભૂમિકા પસંદ કરો:",
    "login_patient_title": "નાગરિક / દર્દી પોર્ટલ",
    "login_patient_desc": "ડિજિટલ આભા કાર્ડ, ૧૦૮ ઇમરજન્સી SOS, જન ઔષધિ દવાઓ, લક્ષણ તપાસ અને પારિવારિક આરોગ્ય.",
