    "help_guide_title": "سوستھیہ سیتو یوزر گائیڈ تہ ہیلپ سنٹر",
    "help_guide_sub": "کردار کی تربیت، مرحلہ وار ہدایات تہ عمومی سوالات",
    "guide_pat_head": "🌾 شہری تہ بیمار فوری گائیڈ",
    "guide_pat_1": "<strong>خود اندراج</strong>: لاگ ان اسکرین پر <em>\"نیا صارف؟ رجسٹر کٔریو\"</em> پر کلک کٔریو۔ اپنا 14 ہندسوں کا آبھا کارڈ حاصل کرنے کے لیے تفصیلات بھریں۔",
    "guide_pat_2": "<strong>ٹیلی کنسلٹیشن کی درخواست</strong>: <em>\"+ ڈاکٹر سے مشورے کی درخواست\"</em> پر کلک کٔریو، ڈاکٹر منتخب کٔریو، علامات لکھیں تہ بھیجیں۔",
    "guide_pat_3": "<strong>ای نسخہ ڈاؤن لوڈ</strong>: جب ڈاکٹر دوا تجویز کرے گا تو نوٹیفکیشن کی آواز آئے گی۔ سرکاری ABDM PDF کے لیے <em>\"📥 PDF ڈاؤن لوڈ کٔریو\"</em> پر کلک کٔریو۔",
    "guide_pat_4": "<strong>نسخہ حذف کٔریو</strong>: ہیلتھ لاكر صاف رکھنے کے لیے ڈاؤن لوڈ کے بعد <em>\"🗑️ حذف کٔریو\"</em> پر کلک کٔریو۔",
    "guide_pat_5": "<strong>ہنگامی 108 SOS</strong>: فوری ایمبولینس کے لیے <em>\"🚨 108 SOS\"</em> یا <em>\"📍 GPS SOS\"</em> پر کلک کٔریو۔",
    "guide_doc_head": "🩺 میڈیکل آفیسر / ڈاکٹر گائیڈ",
    "guide_doc_1": "<strong>او پی ڈی قطار کا انتظام</strong>: قطار میں لائیو بیمار، مشورے کی درخواستیں تہ آشا ریفرلز دکھائے جاتے ہیں۔",
    "guide_doc_2": "<strong>مشورہ فراہم کٔریو</strong>: بیمار پر <em>\"مشورہ دیں تہ نسخہ لکھیں\"</em> منتخب کٔریو۔ جینرک ادویات منتخب کٔریو تہ جمع کٔریو۔",
    "guide_doc_3": "<strong>قطار سے فوری اخراج</strong>: دوا تجویز کرنے کے بعد بیمار قطار سے ہٹ کر تاریخ میں محفوظ ہو جاتا ہے۔",
    "guide_doc_4": "<strong>متحرک PDF ایکسپورٹ</strong>: نسخے پر ABDM قوانین کے مطابق آپ کا نام، رجسٹریشن نمبر تہ ڈیجیٹل دستخط ہوتے ہیں۔",
    "guide_ash_head": "🤝 آشا تہ اے این ایم فرنٹ لائن ورکر گائیڈ",
    "guide_ash_1": "<strong>بیمار کا اندراج تہ ریفرل</strong>: آبھا کارڈ بنانے تہ ڈاکٹر کو ریفر کرنے کے لیے <em>\"+ بیمار کا اندراج تہ ریفر کٔریو\"</em> پر کلک کٔریو۔",
    "guide_ash_2": "<strong>حاملہ خواتین کی دیکھ بھال (ANC)</strong>: حاملہ خواتین کا اندراج کٔریو، ہفتے، بی پی، ہیموگلوبن ریکارڈ کٔریو تہ خطرے کی نگرانی کٔریو۔",
    "guide_ash_3": "<strong>بچوں کے حفاظتی ٹیکے (UIP)</strong>: ویکسین کی خوراکیں (BCG، پینٹاویلنٹ، روٹا وائرس، MR) تہ آنے والی تاریخیں ٹریک کٔریو۔",
    "guide_ash_4": "<strong>ماسٹر فیلڈ رجسٹری</strong>: تمام ریفرلز، ANC ریکارڈ، ٹیکے تہ گھریلو دورے ایک ہی ٹیبل میں وُچھِو۔",
    "guide_adm_head": "👑 ضلعی ہیلتھ ایڈمنسٹریٹر گائیڈ",
    "guide_adm_1": "<strong>عملے کی تعیناتی</strong>: عارضی اسناد کے ساتھ ڈاکٹرز، آشا کارکنان یا ایڈمن شامل کرنے کے لیے <em>\"+ نیا عملہ تعینات کٔریو\"</em> پر کلک کٔریو۔",
    "guide_adm_2": "<strong>عملے کو ہٹانا</strong>: میموری تہ کلاؤڈ سے فوری ہٹانے کے لیے کسی بھی قطار پر <em>\"✕ ہٹائیں\"</em> پر کلک کٔریو۔",
    "guide_adm_3": "<strong>ہسپتال کے بستروں کی تقسیم</strong>: جنرل، آئی سی یو تہ آکسیجن بیڈز کی تعداد کو حقیقی وقت میں ایڈجسٹ کٔریو۔",
    "guide_adm_4": "<strong>بلڈ بینک اسٹاک</strong>: تمام 8 بلڈ گروپس میں خون کی دستیابی کا انتظام کٔریو۔",
