    "sat": "<strong>रक्त बैंक स्टॉक</strong>: सभी 8 रक्त समूहों में रक्त इकाई सूची का प्रबंधन करें।",
    "sd": "<strong>بلڈ بینک اسٹاک</strong>: تمام 8 بلڈ گروپس میں خون کی دستیابی کا انتظام ڪريو۔",
    "tcy": "<strong>ರಕ್ತನಿಧಿ ದಾಸ್ತಾನು</strong>: ಎಲ್ಲಾ 8 ರಕ್ತದ ಗುಂಪುಗಳಲ್ಲಿ ರಕ್ತದ ಯುನಿಟ್ ದಾಸ್ತಾನನ್ನು ನಿರ್ವಹಿಸಿ."
