    "ml": "ജനറൽ കിടക്കകൾ, ഐസിയു, ഓക്സിജൻ കിടക്കകൾ, ഡോക്ടർമാരുടെ ലഭ്യത എന്നിവയുടെ തത്സമയ വിവരങ്ങൾ.",
