    "pa": "ਸਾਰੇ ਪੇਂਡੂ ਭਾਰਤ ਦੇ ਨਾਗਰਿਕਾਂ ਅਤੇ ਪਰਿਵਾਰਾਂ ਲਈ ਅਧਿਕਾਰਤ ਡਿਜੀਟਲ ਸਿਹਤ ਗੇਟਵੇ",
    "or": "ସମଗ୍ର ଗ୍ରାମୀଣ ଭାରତର ନାଗରିକ ଏବଂ ପରିବାର ପାଇଁ ସରକାରୀ ଡିଜିଟାଲ୍ ସ୍ୱାସ୍ଥ୍ୟ ଗେଟୱେ",
