    "mni": "নিবন্ধিত লাইয়েম্বা নির্বাচন তৌবীয়ু, আপনার অসুস্থতার বিবরণ দিন এবং তাৎক্ষণিক ডিজিটাল ওপিডি লাইনে যোগ দিন।",
