    "kn": "ಹಕ್ಕುತ್ಯಾಗ: ಶೈಕ್ಷಣಿಕ ಮತ್ತು ಪ್ರಥಮ ಮಾರ್ಗದರ್ಶನಕ್ಕಾಗಿ ಮಾತ್ರ. ತುರ್ತು ಸಂದರ್ಭದಲ್ಲಿ ವೈದ್ಯರನ್ನು ಸಂಪರ್ಕಿಸಿ.",
