  "ml": "മലയാളം (Malayalam)",
  "mni": "মৈতৈলোন্ / Manipuri",
  "mr": "मराठी (Marathi)",
  "or": "ଓଡ଼ିଆ (Odia)",
  "pa": "ਪੰਜਾਬੀ (Punjabi)",
  "raj": "राजस्थानी / मारवाड़ी (Rajasthani & Marwari)",
  "sat": "ᱥᱟᱱᱛᱟᱲᱤ / Santali",
  "sd": "سنڌي / सिंधी (Sindhi)",
  "ta": "தமிழ் (Tamil)",
